  Q q(String s,String p,String[] o,int c,String e){return new Q(UUID.randomUUID().toString(),s,p,o,c,e);}
  static class Q{String id,subject,prompt,explain;String[] opts;int correct;Q(String i,String s,String p,String[] o,int c,String e){id=i;subject=s;prompt=p;opts=o;correct=c;explain=e;}Q copy(String x){return new Q(id+x,subject,prompt,opts.clone(),correct,explain);}}
